  "implementation": "def solve(case):
    nodes = case.get('nodes')
    required_symbols = case.get('required_symbols', [])
    if not nodes or not isinstance(nodes, list):
        raise ValueError('Invalid case: missing or invalid nodes')
    # Validate node structure and build mappings
    node_map = {}
    children_map = {}
    required_sym_set = set(required_symbols)
    root_id = None
    for node in nodes:
        nid = node.get('id')
        parent = node.get('parent')
        symbol = node.get('symbol')
        depth = node.get('depth')
        removable = node.get('removable')
        utility = node.get('utility')
        if None in (nid, parent, symbol, depth, removable, utility):
            raise ValueError('Node missing required field')
        if parent is None:
            if root_id is not None:
                raise ValueError('Multiple roots')
            root_id = nid
        node_map[nid] = node
        children_map.setdefault(parent, []).append(nid)
    if root_id is None:
        raise ValueError('No root node')
    # Ensure all parent references exist except root's
    for nid, node in node_map.items():
        p = node['parent']
        if p is not None and p not in node_map:
            raise ValueError(f'Parent {p} not found for node {nid}')
    # Build depth-sorted list of removable nodes (excluding required symbols and root)
    removable_candidates = []
    for nid, node in node_map.items():
        if node['removable'] and node['symbol'] not in required_sym_set and nid != root_id:
            removable_candidates.append((node['depth'], nid))
    removable_candidates.sort(key=lambda x: (-x[0], x[1]))  # deeper first, then id asc
    removed = set()
    removal_order = []
    for _, nid in removable_candidates:
        if nid in removed:
            continue
        node = node_map[nid]
        children = children_map.get(nid, [])
        # Check that all children are already removed
        if not all(child in removed for child in children):
            continue
        # Check that no required symbol node is in the subtree (implicitly satisfied because children are removed and required nodes never removed)
        # However, double-check: if there were a required symbol descendant that is not removed because it's required,
        # that descendant would still be in children (or deeper) and not removed, so the above condition fails.
        removed.add(nid)
        removal_order.append(nid)
    retained_ids = sorted([nid for nid in node_map if nid not in removed])
    return {
        'removed_node_ids': removal_order,
        'retained_node_ids': retained_ids
    }
